const defaultValues = {
  email: '',
  name: '',
  is_active: true,
  is_superuser: false,
  is_verified: false,
  role_name: 'staff',
  password: '',
  confirm_password: '',
  phone: '',
  address: ''
}

const showErrors = (field, valueLen, min) => {
  if (valueLen === 0) {
    return `Vui lòng nhập ${field}`
  } else if (valueLen > 0 && valueLen < min) {
    return `${field} phải có ít nhất ${min} kí tự`
  } else {
    return `Vui lòng nhập ${field}`
  }
}

